def-struct(
    Algebra.Abelian(G@Algebra.ctxt.G, $\cdot$@Algebra.ctxt.mul),
    struct(
        Algebra.Group(G@Algebra.ctxt.G, $\cdot$@Algebra.ctxt.mul),
        Logic.forall-typed(
            @a,
            G@Algebra.ctxt.G,
            Logic.forall-typed(
                @b,
                G@Algebra.ctxt.G,
                Eq(Bop.apply($\cdot$@Algebra.ctxt.mul, a, b), Bop.apply($\cdot$@Algebra.ctxt.mul, b, a))
            )
        )
    )
)
